<div class="surface-card table-card"><div class="table-responsive"><table class="table"><thead><tr><th>Title</th><th>Type</th><th>Amount</th><th>Frequency</th><th>Next run</th><th>Mode</th><th>Status</th><th></th></tr></thead><tbody id="recurringRows"></tbody></table></div></div>
