<input type="hidden" name="id"><div class="row g-3"><div class="col-md-6"><label class="form-label">Title</label><input class="form-control" name="title" required></div><div class="col-md-3"><label class="form-label">Type</label><select class="form-select" name="type"><option value="expense">Expense</option><option value="income">Income</option><option value="transfer">Transfer</option></select></div><div class="col-md-3"><label class="form-label">Amount</label><input class="form-control" name="amount" type="number" min="0.01" step="0.01" required></div></div>
<div class="row g-3 mt-0"><div class="col-md-4 recurring-source"><label class="form-label">From account</label><select class="form-select" name="source_account_id"></select></div><div class="col-md-4 recurring-destination d-none"><label class="form-label">To account</label><select class="form-select" name="destination_account_id"></select></div><div class="col-md-4 recurring-category"><label class="form-label">Category</label><select class="form-select" name="category_id"></select></div></div>
