@push('scripts')
<script>
(()=>{const M=MyLedger,body=document.querySelector('#recurringRows'),form=document.querySelector('#recurringForm');let items=[],accounts=[],categories=[];async function refs(){[accounts,categories]=await Promise.all([M.request('/ajax/accounts'),M.request('/ajax/categories')]);refreshForm()}function refreshForm(){const type=form.type.value;M.fillSelect(form.source_account_id,accounts);M.fillSelect(form.destination_account_id,accounts);M.fillSelect(form.category_id,categories.filter(x=>x.type===type),{placeholder:'Select category'});form.querySelector('.recurring-source').classList.toggle('d-none',type==='income');form.querySelector('.recurring-destination').classList.toggle('d-none',type==='expense');form.querySelector('.recurring-category').classList.toggle('d-none',type==='transfer')}async function load(){try{items=await M.request('/ajax/recurring-transactions');body.innerHTML=items.length?items.map(r=>`<tr><td class="fw-semibold">${M.esc(r.title)}</td><td class="text-capitalize">${M.esc(M.typeValue(r.type))}</td><td>${M.money(r.amount)}</td><td class="text-capitalize">Every ${r.interval} ${M.esc(r.frequency)}</td><td>${M.dateTime(r.next_run_at)}</td><td class="text-capitalize">${M.esc(M.typeValue(r.mode))}</td><td><span class="badge ${r.is_active?'text-bg-success':'text-bg-secondary'}">${r.is_active?'Active':'Disabled'}</span></td><td class="text-end"><button class="btn btn-sm btn-icon edit" data-id="${r.id}"><i class="bi bi-pencil"></i></button>${r.is_active?` <button class="btn btn-sm btn-icon text-danger disable" data-id="${r.id}"><i class="bi bi-pause"></i></button>`:''}</td></tr>`).join(''):'<tr><td colspan="8"><div class="empty-state"><i class="bi bi-arrow-repeat"></i>No recurring transactions.</div></td></tr>'}catch(e){M.toast(e.message,'danger')}}document.querySelector('#newRecurring').onclick=()=>{form.reset();form.id.value='';form.is_active.checked=true;form.interval.value=1;const d=new Date(Date.now()+86400000);form.next_run_at.value=new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,16);refs().then(()=>M.modal('recurringModal'))};form.type.onchange=refreshForm;body.onclick=async e=>{const edit=e.target.closest('.edit'),disable=e.target.closest('.disable');if(edit){const r=items.find(x=>String(x.id)===edit.dataset.id);form.reset();form.id.value=r.id;form.title.value=r.title;form.type.value=M.typeValue(r.type);form.amount.value=r.amount;form.frequency.value=r.frequency;form.interval.value=r.interval;form.mode.value=M.typeValue(r.mode);form.is_active.checked=!!r.is_active;form.next_run_at.value=String(r.next_run_at).slice(0,16);await refs();form.source_account_id.value=r.source_account_id||'';form.destination_account_id.value=r.destination_account_id||'';form.category_id.value=r.category_id||'';M.modal('recurringModal')}if(disable&&confirm('Disable this recurring transaction?')){try{await M.request('/ajax/recurring-transactions/'+disable.dataset.id,{method:'DELETE'});M.toast('Recurring transaction disabled.');load()}catch(err){M.toast(err.message,'danger')}}};form.onsubmit=async e=>{e.preventDefault();const d=M.payload(form),id=d.id,type=d.type;delete d.id;if(type==='expense')delete d.destination_account_id;if(type==='income')delete d.source_account_id;if(type==='transfer')delete d.category_id;try{await M.request(id?'/ajax/recurring-transactions/'+id:'/ajax/recurring-transactions',{method:id?'PATCH':'POST',body:JSON.stringify(d)});M.modal('recurringModal','hide');M.toast('Recurring transaction saved.');load()}catch(err){M.errors(form,err)}};Promise.all([refs(),load()])})();
</script>
@endpush
